r=args.source;l=(r/'lib/lmb.c').read_text();a=(r/'lib/alist.c').read_text();f=(r/'boot/image-fdt.c').read_text();b=(r/'boot/image-board.c').read_text();fs=(r/'boot/fdt_support.c').read_text()
def get(s,n):
 import re
 m=re.search(r'(?m)^(?:static )?(?:inline )?(?:long|int|bool|void)\s+'+n+r'\s*\(',s);assert m,n
