p='''#include <stdint.h>\n#include <stdbool.h>\n#include <stdlib.h>\n#include <stdio.h>\n#include <string.h>\n#include <errno.h>\n#include <libfdt.h>\ntypedef uint32_t u32; typedef uint64_t u64; typedef unsigned int uint; typedef unsigned long ulong; typedef uint32_t phys_addr_t; typedef uint32_t phys_size_t;\n#define LMB_NONE 0\n#define LMB_NOMAP 2\n#define LMB_NOOVERWRITE 4\n#define LMB_ALLOC_ANYWHERE 0\n#define LMB_ALIST_INITIAL_SIZE 4\n#define LMB_RGN_OVERLAP 1\n#define LMB_RGN_ADJACENT 2\n#define ALISTF_FAIL 1\n#define ALIST_INITIAL_SIZE 4\n#define LMB_MAP_OP_RESERVE 1\n#define LMB_MAP_OP_ADD 3\n#define LMB_MAP_OP_FREE 2\n#define CONFIG_SYS_FDT_PAD 0x3000\n#define CONFIG_NR_DRAM_BANKS 2\n#define CONFIG_MP 0\n#define IS_ENABLED(x) 0\n#define BOOTSTAGE_ID_COPY_RAMDISK 0\n#define bootstage_mark(x) ((void)0)\n#define memmove_wd(a,b,c,d) memmove(a,b,c)\n#define ARCH_DMA_MINALIGN 64\n#define ALIGN(x,a) (((x)+(a)-1)&~((a)-1))\n#define set_working_fdt_addr(x) ((void)0)\n#define ALIGN_DOWN(x,a) ((x)&~((a)-1))\n#define min(a,b) ((a)<(b)?(a):(b))\n#define max(a,b) ((a)>(b)?(a):(b))\n#define fallthrough __attribute__((fallthrough))\n#define log_debug(...) ((void)0)\n#define debug(...) ((void)0)\n#define fdt_error(s) fprintf(stderr,"fdt: %s\\n",s)\nstruct alist {void *data; uint16_t obj_size,count,alloc,flags;};\nstruct lmb_region {phys_addr_t base;phys_size_t size;u32 flags;};\nstruct lmb {struct alist available_mem,used_mem;bool test;};\nstatic struct lmb lmb;\nenum lmb_mem_type {LMB_MEM_ALLOC_ADDR,LMB_MEM_ALLOC_ANY,LMB_MEM_ALLOC_MAX};\nstruct gd_type {const void *fdt_blob;struct {u64 start,size;} dram[2];};\nstruct fdt_resource {u64 start,end;};\nstatic int fdt_get_resource(const void *f,int n,const char *p,int i,struct fdt_resource *r){return -1;}\nstatic bool fdtdec_get_is_enabled(const void *f,int n){return false;}\nstatic bool fdtdec_get_bool(const void *f,int n,const char *p){return false;} static struct gd_type gd_data,*gd=&gd_data;\nstatic bool alist_full(struct alist *l){return l->count==l->alloc;}\nstatic bool alist_err(struct alist *l){return l->flags & ALISTF_FAIL;}\nstatic int lmb_map_update_notify(phys_addr_t a,phys_size_t b,int c,u32 d){return 0;}\nstatic char *env_get(const char *s){if(!strcmp(s,"fdt_high"))return "50500000";if(!strcmp(s,"initrd_high"))return "ffffffff";return NULL;}\nstatic ulong hextoul(const char *s,char **e){return strtoul(s,e,16);}\nstatic ulong env_get_bootm_mapsize(void){return 0x1000000;}\nstatic ulong env_get_bootm_low(void){return 0x50000000;}\nstatic void flush_cache(ulong a,ulong b){}\nstatic void *mapped; static phys_addr_t mapped_addr;\nstatic void *map_sysmem(phys_addr_t a,ulong n){mapped_addr=a;mapped=calloc(1,n?n:1);return mapped;}\nstatic phys_addr_t map_to_sysmem(void *p){return mapped_addr;}\nstatic void unmap_sysmem(void *p){}\n'''
for n in ['alist_init','alist_expand_to','alist_expand_by']:p+=get(a,n)
