p+=get(f,'boot_fdt_handle_region')+get(f,'boot_fdt_handle_mem_rsv_regions')+get(f,'boot_fdt_add_mem_rsv_regions')+get(b,'boot_ramdisk_high')+get(f,'boot_relocate_fdt')+get(fs,'fdt_find_or_add_subnode')+get(fs,'fdt_setprop_uxx')+get(fs,'fdt_initrd')
p+=f"#define KERNEL_FLAT_SIZE {args.kernel_flat.stat().st_size}u\n"
p+='''\nint main(int argc,char **argv){FILE *fp;long n;void *blob,*fw;char *fdt;ulong flen,start,end;phys_addr_t k=0x50600000,rom=0x2f07afb0;int ret,len,node;const fdt32_t *reg;
if(argc!=3)return 2;fp=fopen(argv[2],"rb");if(!fp)return 12;fseek(fp,0,SEEK_END);n=ftell(fp);rewind(fp);fw=malloc(n);if(fread(fw,1,n,fp)!=(size_t)n)return 13;fclose(fp);node=fdt_path_offset(fw,"/memory@2f030000");reg=fdt_getprop(fw,node,"reg",&len);if(!reg||len!=8||fdt32_to_cpu(reg[0])!=0x2f030000||fdt32_to_cpu(reg[1])!=0x4afb0)return 14;
alist_init(&lmb.available_mem,sizeof(struct lmb_region),4);alist_init(&lmb.used_mem,sizeof(struct lmb_region),4);lmb.test=true;if(lmb_add(fdt32_to_cpu(reg[0]),fdt32_to_cpu(reg[1]))||lmb_add(0x50000000,0x1000000))return 17;gd->fdt_blob=fw;boot_fdt_add_mem_rsv_regions(fw);{phys_addr_t a=0x2f07afa0;if(lmb_alloc_mem(LMB_MEM_ALLOC_ADDR,0,&a,16,LMB_NONE)||lmb_free(a,16,LMB_NONE))return 18;if(lmb_alloc_mem(LMB_MEM_ALLOC_ADDR,0,&a,32,LMB_NONE)!=-EINVAL)return 19;}if(lmb_alloc_mem(LMB_MEM_ALLOC_ADDR,0,&rom,0x5050,LMB_NONE)!=-EFAULT)return 15;
ret=lmb_alloc_mem(LMB_MEM_ALLOC_ADDR,0,&k,KERNEL_FLAT_SIZE,LMB_NONE);if(ret)return 3;ret=boot_ramdisk_high(0x50000000,0x400000,&start,&end);if(ret||start!=0x50000000||end!=0x50400000)return 4;
fp=fopen(argv[1],"rb");if(!fp)return 5;fseek(fp,0,SEEK_END);n=ftell(fp);rewind(fp);blob=malloc(n);if(fread(blob,1,n,fp)!=(size_t)n)return 6;fclose(fp);fdt=blob;boot_fdt_add_mem_rsv_regions(fdt);{phys_addr_t a=0x2f07afa0;if(lmb_alloc_mem(LMB_MEM_ALLOC_ADDR,0,&a,16,LMB_NONE)||lmb_free(a,16,LMB_NONE))return 20;if(lmb_alloc_mem(LMB_MEM_ALLOC_ADDR,0,&a,32,LMB_NONE)!=-EINVAL)return 21;}if(lmb_alloc_mem(LMB_MEM_ALLOC_ADDR,0,&rom,0x5050,LMB_NONE)!=-EFAULT)return 16;flen=n;ret=boot_relocate_fdt(&fdt,&flen);if(ret||mapped_addr<0x50400000||mapped_addr+flen>0x50500000||fdt_check_header(fdt))return 7;ret=fdt_initrd(fdt,start,end);if(ret)return 8; {int count=fdt_num_mem_rsv(fdt),found=0;uint64_t a,z;for(int i=0;i<count;i++){if(!fdt_get_mem_rsv(fdt,i,&a,&z)&&a==start&&z==end-start)found=1;}if(!found)return 11;} {int len,node=fdt_path_offset(fdt,"/chosen"); const fdt32_t *a=fdt_getprop(fdt,node,"linux,initrd-start",&len);if(!a||len!=4||fdt32_to_cpu(*a)!=start)return 9; a=fdt_getprop(fdt,node,"linux,initrd-end",&len);if(!a||len!=4||fdt32_to_cpu(*a)!=end)return 10;} printf("HP bank end=%08x; ROM allocation rejected before and after DT switch; initrd=%08lx..%08lx FDT=%08x..%08lx totalsize=%lu\\n",fdt32_to_cpu(reg[0])+fdt32_to_cpu(reg[1]),start,end,mapped_addr,(ulong)mapped_addr+flen,flen);free(blob);free(fw);free(mapped);free(lmb.available_mem.data);free(lmb.used_mem.data);return 0;}\n''';compile_and_run(args, p, include=(args.host_prefix / 'include',), libraries=('fdt',), run_args=(args.os_dtb, args.firmware_dtb))
